head.b:skin:
:root { 
    --bg: #f4f7fc; 
    --card: #ffffff; 
    --text: #1e293b; 
    --text-muted: #64748b;
    --border: #e2e8f0;
    --input-bg: #f8fafc;

    /* Grasi Warna Soft & Cerah (Bright Soft Gradients) */
    --gradient-primary: linear-gradient(135deg, #4f46e5, #06b6d4);
    --gradient-accent: linear-gradient(135deg, #3b82f6, #10b981);
    --btn-generate-bg: linear-gradient(135deg, #6366f1, #3b82f6);
    --btn-refresh-bg: linear-gradient(135deg, #ec4899, #f43f5e);

    --danger: #ef4444;
    --toast-success: #10b981;
    --toast-info: #3b82f6;

    --shadow-sm: 0 2px 4px rgba(148, 163, 184, 0.05);
    --shadow-md: 0 10px 25px -5px rgba(148, 163, 184, 0.15);
}

* { box-sizing: border-box; }

body { 
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; 
    background: var(--bg); 
    color: var(--text); 
    padding: 20px; 
    margin: 0;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
}

/* Layout Utama Responsif */
.container { 
    width: 100%;
    max-width: 850px; 
    margin: 20px auto; 
    padding: 0 10px; 
}

.panel { 
    background: var(--card); 
    padding: 40px 30px; 
    border-radius: 24px; 
    border: 1px solid var(--border); 
    box-shadow: var(--shadow-md); 
    text-align: center; 
    transition: all 0.3s ease;
}

/* Judul Dengan Gradasi Warna Lembut */
h1 { 
    margin-top: 0; 
    font-size: 2.6rem; 
    font-weight: 800;
    letter-spacing: -1px; 
    background: var(--gradient-primary); 
    -webkit-background-clip: text; 
    -webkit-text-fill-color: transparent; 
    margin-bottom: 10px;
}

p.subtitle { 
    color: var(--text-muted); 
    margin-bottom: 35px; 
    font-size: 1.05rem;
    line-height: 1.6;
}

/* Input Field */
.input-group { 
    width: 100%;
    margin-bottom: 20px; 
}

input { 
    width: 100%; 
    padding: 16px 20px; 
    border-radius: 14px; 
    border: 1px solid var(--border); 
    background: var(--input-bg); 
    color: var(--text); 
    font-size: 1rem; 
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); 
    box-shadow: var(--shadow-sm);
}

input:focus { 
    border-color: #6366f1; 
    background: #ffffff;
    outline: none; 
    box-shadow: 0 0 0 4px rgba(99, 102, 241, 0.15); 
}

/* Tata Letak Tombol Pintar (Grid Responsif Otomatis) */
.button-group { 
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    gap: 12px; 
    margin-top: 15px; 
}

button { 
    padding: 15px 20px; 
    border: none; 
    border-radius: 14px; 
    cursor: pointer; 
    font-weight: 700; 
    font-size: 0.95rem; 
    transition: all 0.2s ease; 
    display: flex; 
    align-items: center; 
    justify-content: center;
    gap: 8px; 
    box-shadow: var(--shadow-sm);
}

button:active {
    transform: scale(0.98);
}

.btn-generate { 
    background: var(--btn-generate-bg); 
    color: #ffffff; 
}
.btn-generate:hover { 
    opacity: 0.95;
    box-shadow: 0 4px 12px rgba(99, 102, 241, 0.25);
}

.btn-refresh { 
    background: var(--btn-refresh-bg); 
    color: #ffffff; 
}
.btn-refresh:hover { 
    opacity: 0.95;
    box-shadow: 0 4px 12px rgba(236, 72, 153, 0.25);
}

.btn-reset { 
    background: #ffffff; 
    color: var(--danger); 
    border: 1px solid rgba(239, 68, 68, 0.3); 
}
.btn-reset:hover { 
    background: rgba(239, 68, 68, 0.04); 
    border-color: var(--danger);
}

.counter-info { 
    font-size: 0.85rem; 
    color: var(--text-muted); 
    margin-top: 25px; 
    text-align: center; 
    font-weight: 500;
    border-top: 1px dashed var(--border);
    padding-top: 15px;
}

/* Kartu Hasil Prompt */
#output { 
    margin-top: 25px; 
    display: flex; 
    flex-direction: column; 
    gap: 16px; 
}

.prompt-box { 
    background: var(--card); 
    padding: 22px; 
    border-radius: 18px; 
    cursor: pointer; 
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1); 
    border: 1px solid var(--border); 
    text-align: left; 
    position: relative; 
    box-shadow: var(--shadow-sm);
}

.prompt-box:hover { 
    border-color: #6366f1; 
    transform: translateY(-2px); 
    box-shadow: 0 12px 20px -8px rgba(99, 102, 241, 0.15);
}

.prompt-tag { 
    display: inline-block; 
    font-size: 0.75rem; 
    background: rgba(99, 102, 241, 0.08); 
    color: #4f46e5; 
    padding: 4px 10px; 
    border-radius: 8px; 
    margin-bottom: 12px; 
    font-weight: 700; 
    text-transform: uppercase; 
    letter-spacing: 0.5px;
}

.prompt-text { 
    font-size: 1.05rem; 
    line-height: 1.6; 
    color: var(--text); 
    font-weight: 500;
    word-break: break-word;
}

.copy-hint { 
    font-size: 0.75rem; 
    color: var(--text-muted); 
    margin-top: 12px; 
    display: flex; 
    align-items: center;
    justify-content: flex-end;
    gap: 4px;
    font-weight: 600;
}

/* Notifikasi Toast Mengambang Modern */
.toast { 
    position: fixed; 
    bottom: -60px; 
    left: 50%; 
    transform: translateX(-50%);
    background: #1e293b; 
    color: white; 
    padding: 14px 28px; 
    border-radius: 50px; 
    font-weight: 600; 
    font-size: 0.95rem;
    box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.3);
    transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); 
    pointer-events: none; 
    z-index: 9999; 
    display: flex;
    align-items: center;
    gap: 8px;
    opacity: 0;
}
.toast.show { 
    bottom: 30px; 
    opacity: 1;
}
.toast.success-style { background: var(--toast-success); }
.toast.info-style { background: var(--toast-info); }

/* --- MEDIA QUERIES (Sistem Responsif HP & Tablet) --- */
@media (max-width: 768px) {
    h1 { font-size: 2.1rem; }
    .panel { padding: 30px 20px; }
    .button-group {
        grid-template-columns: 1fr; /* Susunan tombol otomatis vertikal di Tablet Kecil/HP */
        gap: 10px;
    }
    button { width: 100%; padding: 14px; }
}

@media (max-width: 480px) {
    body { padding: 12px; }
    h1 { font-size: 1.8rem; }
    p.subtitle { font-size: 0.95rem; margin-bottom: 25px; }
    .panel { padding: 25px 15px; border-radius: 20px; }
    .prompt-box { padding: 16px; border-radius: 14px; }
    .prompt-text { font-size: 0.95rem; }
}

body.script:
//
    const database = {
        styles: [
"Cyberpunk Aesthetic", "Steampunk Engine Core", "Surrealism oil painting", "Hyper-realistic 3D Digital Art",
"Futuristic Solarpunk", "Dark Fantasy Grimdark", "Mythological Ethereal Art", "Synthwave Retro-futurism",
