"Fashion Editorial High-Glamour", "Paparazzi Flash Aesthetics", "Gothic Architecture Photo", "Candid Portrait Shallow Depth",
"Studio Lighting Rim Glow", "Rembrandt Lighting Portrait", "Volumetric Foggy Cinematic", "Cyberpunk Street Photography",
"Documentary Gritty Realism", "Architectural Minimalist Photo", "Food Photography Editorial", "Product Showcase Studio Shot",
"X-Ray Skeletal Art", "Satellite Earth Topography", "Thermal Imaging Heat-Map", "Microscopic Cell Structure",
"Pinhole Camera Distorted", "Fisheye Lens Action Shot", "Bokeh Background Pastel", "Light Painting Long Exposure",
"High-Speed Water Splash", "Storm Chaser Lightning Photo", "Volcanic Eruption Dramatic", "Aurora Borealis Neon Sky",
"Desert Dunes Pattern Shot", "Glacier Ice Caves Blue", "Deep Jungle Canopy Flare", "Foggy Mountain Ridge Sunrise",
"Urban Exploration Abandoned", "Traditional Japanese Kimono Silk", "Indonesian Kebaya Embroidery", "Indian Bollywood Sari Gold",
"Chinese Cheongsam Brocade", "Korean Hanbok Pastel Elegance", "Scottish Highland Kilt Tartan", "Mexican Huipil Hand-Woven",
"Native American Beaded Art", "Maori Tā Moko Carving", "African Kente Cloth Vibrant", "Zulu Beaded Geometric",
"Massai Vibrant Ochre Art", "Tibetan Mandala Thangka", "Peruvian Inca Geometric", "Aztec Calendar Stone",
"Mayan Jade Carving", "Inuit Soapstone Sculpture", "Aborginal Australian Dot Painting", "Persian Miniature Painting",
"Ottoman Illuminating Art", "Moorish Arched Architecture", "Byzantine Golden Mosaic", "Viking Urnes Style Carving",
"Celtic High Cross Relief", "Slavic Khokhloma Painting", "Gzhel Blue Ceramic Style", "Matryoshka Folk Art",
"Portuguese Azulejo Tile", "Flamenco Red Ruffle Motion", "Venetian Carnival Mask", "Bavarian Lederhosen Embroidery",
"Greek Key Meander Motif", "Roman Triumphal Relief", "Egyptian Papyrus Illustration", "Mesopotamian Cuneiform Tablet",
"Persian Carpet Intricate", "Navajo Rug Handwoven", "Huichol Yarn Painting", "Alebrije Folk Art Sculpture",
"Talavera Mexican Pottery", "Murano Glass Blown Color", "Delft Blue Pottery Art", "Meissen Porcelain Detailed",
"Limoges Enamel Miniature", "Cloisonné Enamel Inlay", "Filigree Silver Wire Art", "Repoussé Metal Relief",
"Damascening Gold Inlay", "Champlevé Enamel Inlay", "Niello Dark Metal Inlay"
        ],
        lighting: [
            "cinematic lighting", "volumetric god rays", "neon glow", "golden hour warmth", "dramatic chiaroscuro",
            "bioluminescent luminescence", "cyberpunk moody neon", "soft diffuse morning light", "rim lighting, epic mood",
            "studio lighting, clean highlights", "mystical twilight shadow", "harsh direct sunlight with deep shadows",
            "quantum particle glow", "iridescent pearlescent light", "ambient occlusion, soft shadows"
        ],
        details: [
            "intricate details", "hyper-detailed textures", "masterpiece composition", "award-winning digital art",
            "breathtaking environment", "highly polished finish", "complex geometry", "octane render crispness",
            "photorealistic fidelity", "epic scale, magnificent", "surreal details", "unreal engine 5 render quality",
            "fine lines and sharp focus", "4k resolution rendering", "impeccable craftsmanship"
        ],
        cameras: [
            "shot on 85mm lens", "macro photography detail", "wide-angle panoramic view", "aerial drone perspective",
            "isometric 3D view", "close-up portrait angle", "dramatic low-angle shot", "orthographic view, architectural render",
            "ray-traced reflections", "depth of field, blurred background", "Hasselblad medium format capture"
        ],
        platforms: [
            "ArtStation trending", "Pixiv masterpiece", "Behance featured", "CGSociety highlight", "DeviantArt top list"
        ]
    };

    const defaultSubjects = ["Cybernetic Deity", "Enchanted Ancient Forest", "Astronaut on Floating Island", "Lost Futuristic City", "Mythical Phoenix"];

    function hitungKombinasi() {
        const total = database.styles.length * database.lighting.length * database.details.length * database.cameras.length * database.platforms.length;
        document.getElementById('math-info').innerText = `Sistem siap mengacak dari sekitar ${total.toLocaleString()}+ kombinasi gaya dasar otomatis (Belum termasuk variasi subjek Anda).`;
    }

    function getRandomElement(arr) {
        return arr[Math.floor(Math.random() * arr.length)];
    }

    function generate() {
        const subjectInput = document.getElementById('subject').value.trim();
        const finalSubject = subjectInput || getRandomElement(defaultSubjects);

        const output = document.getElementById('output');
        output.innerHTML = ""; 

        for(let i = 0; i < 5; i++) {
            const style = getRandomElement(database.styles);
            const light = getRandomElement(database.lighting);
            const detail = getRandomElement(database.details);
            const cam = getRandomElement(database.cameras);
            const platform = getRandomElement(database.platforms);

            const promptText = `${finalSubject}, ${style}, ${light}, ${detail}, ${cam}, featured on ${platform}, hyperrealistic, sharp focus, --ar 16:9 --v 6.0`;

            const card = document.createElement('div');
            card.className = 'prompt-box';

            const tag = document.createElement('span');
            tag.className = 'prompt-tag';
            tag.innerText = style.split(' ')[0] + " Art"; 

            const textDiv = document.createElement('div');
            textDiv.className = 'prompt-text';
            textDiv.innerText = promptText;

            const hint = document.createElement('span');
            hint.className = 'copy-hint';
            hint.innerText = "Salin Prompt 📋";

            card.appendChild(tag);
            card.appendChild(textDiv);
            card.appendChild(hint);

            card.onclick = () => {
                navigator.clipboard.writeText(promptText).then(() => {
                    showToast("Prompt berhasil disalin! 📋", "success");
                });
            };

            output.appendChild(card);
        }
    }

    function refreshStyles() {
        const subjectInput = document.getElementById('subject').value.trim();
        if (!subjectInput && document.getElementById('output').children.length === 0) {
            showToast("Ketik subjek terlebih dahulu atau klik Generate!", "info");
            return;
        }
        generate();
        showToast("Gaya seni berhasil diacak ulang! 🔄", "info");
    }

    function resetForm() {
        document.getElementById('subject').value = "";
        document.getElementById('output').innerHTML = "";
        showToast("Formulir telah dibersihkan! 🗑️", "info");
    }

    function showToast(message, type) {
        const toast = document.getElementById('toast');
        toast.innerText = message;
        toast.className = "toast";

        if(type === "success") {
            toast.classList.add("show", "success-style");
        } else if(type === "info") {
            toast.classList.add("show", "info-style");
        } else {
            toast.classList.add("show");
        }

        setTimeout(() => { 
            toast.classList.remove("show"); 
        }, 2000);
    }

    window.onload = hitungKombinasi;
//
